cd /tmp && cat > nan.c <<'EOF'
#include <stdio.h>
#include <math.h>
volatile double z=0.0; volatile long long n=0;
int main(){
  double x = z/(double)n;
  printf("x=%.1f\n", x);
  printf("A -4.343*log(x)   = %.1f\n", -4.343*log(x));
  printf("B -10*log10(x)    = %.1f\n", -10.0*log10(x));
  printf("C -4.343*log(-x)  = %.1f\n", -4.343*log(-x));
  printf("D log(x)          = %.1f\n", log(x));
  printf("E -10*log10(1.0)  = %.1f\n", -10.0*log10(1.0));
  printf("F 100*x           = %.1f\n", 100.0*x);
  printf("G -x              = %.1f\n", -x);
  return 0;
}
EOF
gcc -O2 -o nan nan.c -lm && ./nan
